import{_ as p,a0 as o,w as d,s as h,I as t,x as i,a1 as a,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用統一阻止列表和白名單來更新主機文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用統一阻止列表和白名單來更新主機文件 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用統一阻止列表和白名單來更新主機文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用統一阻止列表和白名單來更新主機文件 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170117 This Script Updates Hosts Files Using a Multi-Source Unified Block List With Whitelisting","title":"使用統一阻止列表和白名單來更新主機文件","tag":"201707","desc":""},"relativePath":"201707/20170117 This Script Updates Hosts Files Using a Multi-Source Unified Block List With Whitelisting.md","filePath":"[post].md"}'),r={name:"201707/20170117 This Script Updates Hosts Files Using a Multi-Source Unified Block List With Whitelisting.md"};function g(k,s,u,b,c,f){const e=o("Link");return d(),h("div",null,[s[19]||(s[19]=t("h1",{id:"使用統一阻止列表和白名單來更新主機文件",tabindex:"-1"},[i("使用統一阻止列表和白名單來更新主機文件 "),t("a",{class:"header-anchor",href:"#使用統一阻止列表和白名單來更新主機文件","aria-label":"Permalink to “使用統一阻止列表和白名單來更新主機文件”"},"​")],-1)),s[20]||(s[20]=t("p",null,[t("img",{src:"https://irp-cdn.multiscreensite.com/58a25abc/dms3rep/multi/desktop/host-400x300.jpg",alt:""})],-1)),s[21]||(s[21]=t("p",null,"網上有許多持續維護的含有不同垃圾域的有用列表。將這些列表複製到你的主機文件中可以輕鬆阻止大量的域，你的系統將根本不用去連接它們。此方法可以在不安裝瀏覽器插件的情況下工作，並且將為系統上任何瀏覽器（和任何其他程序）提供阻止操作。",-1)),t("p",null,[s[1]||(s[1]=i("在本教程中，我將向你展示如何在 Linux 中啓動並運行 Steven Black 的",-1)),a(e,{href:"https://github.com/StevenBlack/hosts"},{default:n(()=>[...s[0]||(s[0]=[i("統一主機腳本",-1)])]),_:1}),s[2]||(s[2]=i("。該腳本將使用來自多個來源的最新已知的廣告服務器、網絡釣魚網站和其他網絡垃圾的地址來更新你的計算機主機文件，同時提供一個漂亮、乾淨的方式來管理你自己的黑名單/白名單，其分別來自於該腳本管理的各個列表。",-1))]),s[22]||(s[22]=l(`<p>在將 30,000 個域放入主機文件之前，需要注意兩點。首先，這些巨大的列表包含可能需要解除封鎖的服務器，以便進行在線購買或其他一些臨時情況。如果你弄亂了你的主機文件，你要知道網上的某些東西可能會出現問題。為了解決這個問題，我將向你展示如何使用方便的打開/關閉開關，以便你可以快速禁用你的阻止列表來購買喜馬拉雅鹽霧燈（它是等離子燈）。我仍然認為這些列表的目的之一是將所有的一切都封鎖（有點煩人，直到我想到了做一個關閉開關）。如果你經常遇到你需要的服務器被阻止的問題，只需將其添加到白名單文件中即可。</p><p>第二個問題是性能受到了輕微的影響, 因為每次調用一個域時, 系統都必須檢查整個列表。只是有一點點影響, 而沒有大到讓我因此而放棄黑名單，讓每一個連接都通過。你具體要怎麼選擇自己看着辦。</p><p>主機文件通過將請求定向到 127.0.0.1 或 0.0.0.0（換句話説定向到空地址）來阻止請求。有人説使用 0.0.0.0 是更快，問題更少的方法。你可以將腳本配置為使用 <code>-ip nnn.nnn.nnn.nnn</code> 這樣的 ip 選項來作為阻止 ip，但默認值是 0.0.0.0，這是我使用的值。</p><p>我曾經將 Steven Black 的腳本做的事每隔一段時間就手動做一遍，進到每一個站點，將他們的列表拷貝/粘貼到我的主機文件中，做一個查找替換將其中的 127 變成 0 等等。我知道整件事情可以自動化，這樣做有點傻，但我從來沒有花時間解決這個問題。直到我找到這個腳本，現在這事已經是一個被遺忘的雜務。</p><p>讓我們先下載一份最新的 Steven Black 的代碼拷貝（大約 150MB），以便我們可以進行下一步。你需要安裝 git，因此如果還沒安裝，進入到終端輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install git</span></span></code></pre></div><p>安裝完之後，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir unifiedhosts </span></span>
<span class="line"><span>cd unifiedhosts</span></span>
<span class="line"><span>git clone https://github.com/StevenBlack/hosts.git</span></span>
<span class="line"><span>cd hosts</span></span></code></pre></div>`,8)),t("p",null,[s[4]||(s[4]=i("當你打開了 Steven 的腳本時，讓我們來看看有什麼選項。該腳本有幾個選項和擴展，但擴展我不會在這裏提交，但如果你到了這一步並且你有興趣，",-1)),a(e,{href:"https://github.com/StevenBlack/hosts/blob/master/readme.md"},{default:n(()=>[...s[3]||(s[3]=[i("readme.md",-1)])]),_:1}),s[5]||(s[5]=i(" 可以告訴你所有你需要知道的。",-1))]),s[23]||(s[23]=l(`<p>你需要安裝 python 來運行此腳本，並且與版本有關。要找到你安裝的 Python 版本，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>python --version</span></span></code></pre></div><p>如果你還沒安裝 Python:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install python</span></span></code></pre></div><p>對於 Python 2.7，如下所示，輸入 <code>python</code> 來執行腳本。對於 Python 3，在命令中的 <code>python</code> 替換成 <code>python3</code>。執行後，該腳本會確保它具有每個列表的最新版本，如果沒有，它會抓取一個新的副本。然後，它會寫入一個新的主機文件，包括了你的黑名單/白名單中的任何內容。讓我們嘗試使用 <code>-r</code> 選項來替換我們的當前的主機文件，而 <code>-a</code> 選項可以腳本不會問我們任何問題。回到終端：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>python updateHostsFile.py -r -a</span></span></code></pre></div><p>該命令將詢問你的 root 密碼，以便能夠寫入 <code>/etc/</code>。為了使新更新的列表處於激活狀態，某些系統需要清除 DNS 緩存。在同一個硬件設備上，我觀察到不同的操作系統表現出非常不同的行為，在沒有刷新緩存的情況下不同的服務器變為可訪問/不可訪問所需的時間長度都不同。我已經看到了從即時更新（Slackware）到重啓更新（Windows）的各種情況。有一些命令可以刷新 DNS 緩存，但是它們在每個操作系統甚至每個發行版上都不同，所以如果沒有生效，只需要重新啓動就行了。</p><p>現在，只要將你的個人例外添加到黑名單/白名單中，並且只要你想要更新主機文件，運行該腳本就好。該腳本將根據你的要求調整生成的主機文件，每次運行文件時會自動追加你額外的列表。</p><p>最後，我們來創建一個打開/關閉開關，對於打開和關閉功能每個都創建一個腳本，所以回到終端輸入下面的內容創建關閉開關（用你自己的文本編輯器替換 leafpad）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>leafpad hosts-off.sh</span></span></code></pre></div><p>在新文件中輸入下面的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span>sudo mv /etc/hosts /etc/hostsDISABLED</span></span></code></pre></div><p>接着讓它可執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod +x hosts-off.sh</span></span></code></pre></div><p>相似地，對於打開開關：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>leafpad hosts-on.sh</span></span></code></pre></div><p>在新文件中輸入下面的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span>sudo mv /etc/hostsDISABLED /etc/hosts</span></span></code></pre></div><p>最後讓它可執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod +x hosts-on.sh</span></span></code></pre></div><p>你所需要做的是為每個腳本創建一個快捷方式，標記為 HOSTS-ON 和 HOSTS-OFF，放在你能找到它們的地方。</p><hr>`,22)),t("p",null,[s[7]||(s[7]=i("via: ",-1)),a(e,{href:"https://www.darrentoback.com/this-script-updates-hosts-files-using-a-multi-source-unified-block-list-with-whitelisting"},{default:n(()=>[...s[6]||(s[6]=[i("https://www.darrentoback.com/this-script-updates-hosts-files-using-a-multi-source-unified-block-list-with-whitelisting",-1)])]),_:1})]),t("p",null,[s[11]||(s[11]=i("作者：",-1)),a(e,{href:"https://www.darrentoback.com/about-me"},{default:n(()=>[...s[8]||(s[8]=[i("dmt",-1)])]),_:1}),s[12]||(s[12]=i(" 譯者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:n(()=>[...s[9]||(s[9]=[i("geekpi",-1)])]),_:1}),s[13]||(s[13]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[10]||(s[10]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[16]||(s[16]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[14]||(s[14]=[i("LCTT",-1)])]),_:1}),s[17]||(s[17]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...s[15]||(s[15]=[i("Linux中國",-1)])]),_:1}),s[18]||(s[18]=i(" 榮譽推出",-1))])])}const v=p(r,[["render",g]]);export{C as __pageData,v as default};
